/* D121：甲方对接门户。纯浏览器内存演示，刷新恢复样例；不读取团队侧线程。 */
const egState = {thread:'T1',level:'list',preview:'正常',contact:'Lee',read:false,signed:false,answer:'',messages:{},pending:{},input:'',aiVisible:true};
const egThreads = [
  {id:'T1',title:'账单中心二期 SOW',style:'瀑布',unread:2,status:'待你签认',project:'账单中心'},
  {id:'T2',title:'十月优化清单',style:'清单',unread:1,status:'澄清中',project:'账单中心'},
  {id:'T3',title:'导出权限问题',style:'对话',unread:1,status:'已通知变更结果',project:'账单中心'}
];
const egMilestones = [
  {id:'M1',title:'需求确认',date:'2026-10-15',phase:0,status:'待你签认'},
  {id:'M2',title:'导出能力',date:'2026-10-27',phase:1,status:'4 / 6 项完成'},
  {id:'M3',title:'权限与审计',date:'2026-10-30',phase:1,status:'待开始'},
  {id:'M4',title:'交付说明',date:'2026-11-03',phase:2,status:'待开始'},
  {id:'M5',title:'交付验收',date:'2026-11-06',phase:2,status:'待验收'}
];
const egItems = [
  ['账期筛选','高',['当你选择账期时，列表应仅显示该账期账单。','当账期无账单时，应显示空结果说明。']],
  ['账单详情','高',['当你打开账单时，应显示金额、税额和账期。','当账单不存在时，应显示不可用说明。']],
  ['金额口径','高',['当你查看账单时，金额应按约定币种展示。','当金额含小数时，应按两位小数舍入。']],
  ['需求确认记录','中',['当你签认版本时，应保留签认人和版本号。']],
  ['CSV 导出','高',['当你导出账单时，应生成 CSV 文件。','当文件包含中文时，应可正确读取。']],
  ['字段排序','高',['当你导出时，字段应按你提供的模板排序。','当模板字段缺失时，应给出明确说明。']],
  ['文件命名','中',['当你下载导出文件时，文件名应包含账期。']],
  ['导出权限','高',['当财务角色导出时，应允许导出金额。','当无权限角色导出时，应拒绝并说明原因。']],
  ['审计记录','高',['当你导出时，应记录操作者和时间。','当你查询审计记录时，应支持按账期筛选。']],
  ['失败提示','中',['当导出失败时，应显示可重试提示。']],
  ['大账单提示','中',['当账单超过约定大小时，应显示等待提示。']],
  ['使用说明','中',['当你打开交付说明时，应可查看导出步骤。']],
  ['演示入口','中',['当你打开演示链接时，应可查看导出示例。']],
  ['交付清单','高',['当你验收时，应逐项展示交付内容与对应标准。']]
].map((v,i)=>({id:'需求项 '+String(i+1).padStart(2,'0'),title:v[0],priority:v[1],criteria:v[2],phase:i<4?0:i<11?1:2}));
const egChecklist = [
  ['账期筛选记忆','已确认'],['空结果提示','已确认'],['文件名包含账期','已确认'],
  ['审计角色导出范围','澄清中'],['大账单等待提示','澄清中'],
  ['字段顺序调整','已纳入需求'],['失败重试提示','已纳入需求'],['自动报价','不做：不在本期范围内，由 Morgan 说明']
];
// 未批准草稿不参与任何门户渲染。
const egDrafts = [];
const egConversion = {requirement:null,version:null,project:'p1'};
const egInputStyle = 'width:100%;box-sizing:border-box;padding:10px;border:1px solid var(--border);border-radius:8px;background:var(--card);color:var(--fg);font:inherit';
function egEsc(v){return String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function egBtn(t,action,kind='',disabled=false){return `<button type="button" class="btn ${kind}" onclick="${action}" ${disabled?'disabled':''}>${t}</button>`;}
function egReadonly(){return egState.contact==='Zhao';}
function egWritable(){return !egReadonly()&&egState.preview!=='异常';}
function egReason(){return egReadonly()?'你当前以 Zhao 只读身份查看，不能提交、回答或签认。':egState.preview==='异常'?'连接异常，提交暂不可用；请恢复正常状态后重试。':'';}
function egSet(k,v){egState[k]=v;route();}
function egSelect(id){egState.thread=id;egState.level='chat';egState.input='';go('portal');route();}
function egModal(title,body,footer){openModal(`<div class="stack" style="padding:24px"><div class="row"><h3 class="grow">${title}</h3>${egBtn('关闭','closeModal()','ghost sm')}</div>${body}<div id="egError" class="note danger" role="alert" hidden></div><div class="row wrap">${footer}</div></div>`);}
function egError(t){const e=document.getElementById('egError');if(e){e.hidden=false;e.textContent=t;}else toast(t);}
function egFrame(active,body){return `<div class="portal-wrap" style="max-width:1440px">
  <div class="portal-head"><div class="brand-mark" style="background:#0f766e">N</div><div><b style="font-family:var(--font-head);font-size:18px">Northwind Studio · 需求门户</b><div class="muted small">你好，${egState.contact}（Contoso）· 品牌来自团队配置</div></div><a class="btn sm" style="margin-left:auto" href="#/overview">${I('arrow-left')}返回团队控制台（原型导航）</a></div>
  <div class="tabs" style="flex-wrap:wrap">${[['对接会话','portal'],['需求确认单','portal-baseline/BL-7'],['进度','portal-progress'],['交付验收','portal-accept']].map(([t,r])=>`<button class="${active===r?'on':''}" onclick="go('${r}')">${t}</button>`).join('')}</div>
  <div class="row wrap small" style="margin-bottom:16px"><span>联系人预览</span>${['Lee','Zhao'].map(n=>`<button class="chip ${egState.contact===n?'on':''}" onclick="egSet('contact','${n}')">${n} · ${n==='Lee'?'可签认':'只读'}</button>`).join('')}<span class="muted">仅为原型身份预览</span></div>${egReason()?`<div class="note warn">${egReason()}</div>`:''}${body}</div>`;}
function egMessage(author,text,ai=false){return `<div class="bubble"><div class="row wrap small"><b>${ai&&!egState.aiVisible?'对接组':egEsc(author)}</b>${ai&&egState.aiVisible?'<span class="badge b-info">AI 助手</span>':''}<span class="muted xs">${author===egState.contact?'刚刚':'10-12'}</span></div><p style="white-space:pre-wrap;overflow-wrap:anywhere">${egEsc(text)}</p></div>`;}
function egThreadList(){return card('需求话题',`<div class="stack">${egThreads.map(t=>`<button type="button" class="inbox-item" style="width:100%;text-align:left;color:inherit;background:var(--card)" onclick="egSelect('${t.id}')" aria-pressed="${egState.thread===t.id}"><b>${t.id} · ${egEsc(t.title)}</b><div class="row wrap"><span class="chip ${egState.thread===t.id?'on':''}">${t.style}</span><span class="badge b-info">未读 ${t.unread}</span></div><div class="small muted">${t.id==='T1'&&egState.signed?'已签认':egEsc(t.status)}</div></button>`).join('')}${egBtn('新建话题','egNewTopic()','primary',!egWritable())}</div>`,{icon:'messages-square'});}
function egNewTopic(){if(!egWritable())return;egModal('新建话题',`<label class="stack">话题名称<input id="egTopic" maxlength="200" style="${egInputStyle}"></label><label class="stack">需求方式<select id="egTopicStyle" style="${egInputStyle}"><option>对话</option><option>清单</option><option>瀑布</option></select></label>`,egBtn('创建','egCreateTopic()','primary'));}
function egCreateTopic(){if(!egWritable())return;const title=document.getElementById('egTopic').value.trim();if(!title)return egError('请填写话题名称。');const id='T'+(egThreads.length+1);egThreads.push({id,title,style:document.getElementById('egTopicStyle').value,unread:0,status:'已接收',project:'尚未关联项目'});closeModal();egSelect(id);}
function egUpload(kind){if(!egWritable())return;egModal(kind==='list'?'粘贴清单':'上传需求文档',kind==='list'?`<p class="note info">可粘贴多行或上传表格，提交后逐条显示。瀑布与清单需求须签认后再开始。</p><label class="stack">每行一条需求<textarea id="egList" rows="6" maxlength="20000" style="${egInputStyle}"></textarea></label><label class="stack">或上传表格<input id="egFile" type="file" accept=".csv,.xlsx,.xls"></label>`:`<p class="note info">我们会提取阶段、里程碑和需求项，整理成需求确认单给你签认。</p><label class="stack">需求文档<input id="egFile" type="file" accept=".docx,.doc,.pdf,.txt"></label>`,egBtn('提交',`egReceive('${kind}')`,'primary'));}
function egReceive(kind){if(!egWritable())return;const f=document.getElementById('egFile').files[0],raw=kind==='list'?document.getElementById('egList').value.trim():'';if(!raw&&!f)return egError('请填写清单或选择文件。');if(f&&f.size>25*1024*1024)return egError('单个附件不得超过 25MB。');if(kind==='list'){egState.thread='T2';egDrafts.push({author:'Iris',status:'草稿待对接人确认后发送',approved:false,content:raw||f.name});egState.pending.T2=(egState.pending.T2||[]).concat(raw?raw.split(/\r?\n/).map(s=>s.trim()).filter(Boolean):['表格附件：'+f.name]);}const id=egState.thread;egState.messages[id]=(egState.messages[id]||[]).concat([{author:egState.contact,text:raw||'已上传：'+f.name},{author:'对接组',text:'已收到，正在整理'}]);closeModal();egState.level='chat';route();}
function egSend(){if(!egWritable())return;const text=egState.input.trim();if(!text)return;const id=egState.thread;egState.messages[id]=(egState.messages[id]||[]).concat([{author:egState.contact,text},{author:'对接组',text:'已收到，正在整理'}]);egState.input='';route();}
function egAnswer(){if(!egWritable()||egState.answer)return;const answer=document.getElementById('egAnswer').value.trim();if(!answer)return toast('请先填写回答。');egState.answer=answer;egState.messages.T3=(egState.messages.T3||[]).concat([{author:egState.contact,text:answer}]);route();toast('回答已提交');}
function egConversation(){const t=egThreads.find(x=>x.id===egState.thread)||egThreads[0];let body='';
  if(t.id==='T1')body=mdPortalAttachments(!egWritable())+mdApprovedAnswer()+egMessage('Lee','已上传《账单中心二期需求说明书.docx》，请按阶段整理。')+egMessage('Iris','需求说明已整理，请查看需求确认单；范围、日期和承诺由 Morgan 确认。',true)+card('需求草案 · BL-7 v1',`<p>账单中心二期：账单查询、导出与权限、交付说明。</p><div class="row wrap"><span class="badge b-info">3 个阶段</span><span class="chip">5 个里程碑</span><span class="chip">14 条需求项</span><span class="chip">21 条验收标准</span><span class="chip">2 条范围外</span></div><p>状态：${egState.signed?'已签认 · 成为基线':'待甲方签认'}</p>${egBtn('查看需求确认单',"go('portal-baseline/BL-7')",'primary')}`)+egMessage('Morgan','请签认此版本。签认后成为基线，之后的改动走变更。')+card('变更 · IN-2042',`<dl class="kv"><dt>状态</dt><dd>超出时间容差，待甲方确认</dd><dt>影响</dt><dd>交付日期变化需由你确认</dd></dl>${egBtn('查看影响并确认',"go('portal-change-approval/IN-2042')",'primary')}`)+card('里程碑进度',`<b>M2 导出能力：4 / 6 项完成，预计 10-27</b><p>发布：Morgan · 10-12</p>${egState.aiVisible?'<p class="muted small">Iris · AI 助手起草，Morgan 批准后发出</p>':''}${egBtn('查看进度',"go('portal-progress')",'sm')}`)+card('交付验收 · BIL#3',`<dl class="kv"><dt>状态</dt><dd>待验收</dd><dt>交付内容</dt><dd>CSV 导出、字段排序、失败重试提示</dd></dl>${egBtn('去验收',"go('portal-accept')",'primary')}`);
  else if(t.id==='T2')body=egMessage('Lee','这是十月的 8 条优化清单，请逐条确认。')+egMessage('Morgan','已逐条整理。清单需求须完成签认后再开始；不做项已附理由。')+card('十月优化清单',`<div class="stack">${egChecklist.map((v,i)=>`<div class="row wrap"><span class="grow">${i+1}. ${v[0]}</span><span class="badge ${v[1].startsWith('不做')?'b-stale':v[1]==='澄清中'?'b-warn':'b-ok'}">${v[1]}</span></div>`).join('')}</div><p class="small muted">已确认 3 · 澄清中 2 · 已纳入需求 2 · 不做 1</p>`)+card('新增清单',egState.pending.T2?`<div class="stack">${egState.pending.T2.map((x,i)=>`<div>${i+1}. ${egEsc(x)} <span class="badge b-info">已收到，正在整理</span></div>`).join('')}</div>`:'<div class="empty">尚未粘贴新清单。你可以在下方粘贴多行或上传表格。</div>');
  else if(t.id==='T3')body=egMessage('Lee','请明确导出权限里的审计角色范围。')+egMessage('Morgan','此问题按容差判定走快速通道，无需签认，已转为变更并通知你。请补充金额字段的权限口径。')+card('澄清问题',`<b>审计角色是否可导出金额字段？</b>${egState.answer?`<p>你的回答：${egEsc(egState.answer)}</p><span class="badge b-ok">已回答</span>`:`<label class="stack" style="margin-top:12px">你的回答<textarea id="egAnswer" rows="3" maxlength="2000" style="${egInputStyle}" ${!egWritable()?'disabled':''}></textarea></label>${egBtn('提交回答','egAnswer()','primary',!egWritable())}`}`)+card('快速通道变更通知','<dl class="kv"><dt>状态</dt><dd>已转为变更，已通知甲方</dd><dt>签认</dt><dd>按容差判定无需签认</dd><dt>负责对接</dt><dd>Morgan</dd></dl>');
  else body=card('话题信息',`<dl class="kv"><dt>主题</dt><dd>${egEsc(t.title)}</dd><dt>方式</dt><dd>${t.style}</dd><dt>状态</dt><dd>已接收</dd></dl>`)+card('会话记录','<div class="empty">你可以直接输入需求，或上传文档、粘贴清单。</div>');
  body+=(egState.messages[t.id]||[]).map(m=>egMessage(m.author,m.text)).join('');
  return card(t.id+' · '+egEsc(t.title),`<div class="stack">${egState.preview==='空'?'<div class="empty">暂无会话消息；你可以发送第一条需求。</div>':body}</div>`)+card('发送需求',`<div class="row wrap">${egBtn('上传需求文档',"egUpload('document')",'sm',!egWritable())}${egBtn('粘贴清单',"egUpload('list')",'sm',!egWritable())}<span class="chip">直接输入 · 对话</span></div><label class="stack" style="margin-top:12px">你的消息<textarea id="egInput" onpaste="mdPaste(event,'portal-'+egState.thread)" rows="3" maxlength="20000" style="${egInputStyle}" oninput="egState.input=this.value;document.getElementById('egSend').disabled=!this.value.trim()" ${!egWritable()?'disabled':''}>${egEsc(egState.input)}</textarea></label>${mdComposerTools({id:"portal-"+t.id,input:"egInput",team:false,disabled:!egWritable(),reason:egReason()})}<div class="row wrap" style="margin-top:12px"><button id="egSend" class="btn primary" onclick="egSend()" ${!egWritable()||!egState.input.trim()?'disabled':''}>发送</button><span class="small muted">${egReason()||'消息不能为空。收到需求后会整理并由对接人确认。'}</span></div>`);
}
function egDetails(){const id=egState.thread;return card('本线程的需求确认单',id==='T1'?`<b>BL-7 v1</b><p>${egState.signed?'已签认 · 成为基线；之后的改动走变更':'待甲方签认'}</p>${egBtn('查看需求确认单',"go('portal-baseline/BL-7')",'sm')}`:id==='T2'?'<p>清单式 · 待澄清并整理需求确认单</p><span class="badge b-warn">签认前不开始</span>':id==='T3'?'<p>对话式 · 快速通道</p><span class="badge b-ok">容差内无需签认，已通知你</span>':'<p>尚未形成需求确认单，正在整理。</p>')+card('里程碑与交付',`<dl class="kv"><dt>项目</dt><dd>${egEsc(egThreads.find(t=>t.id===id).project)}</dd><dt>里程碑</dt><dd>${id==='T1'?'M2 导出能力 · 4 / 6 · 预计 10-27':'尚无本线程里程碑'}</dd><dt>交付</dt><dd>${id==='T1'?'BIL#3 · 待验收':'尚无本线程交付包'}</dd></dl>`)+card('对接组',`<p><b>Morgan</b> · 对接人（人类）</p><p class="small">负责范围、日期、价格与承诺。</p><p>${egState.aiVisible?'<b>Iris</b> · <span class="badge b-info">AI 助手</span>':'对接组助手'}</p><p class="small muted">协助整理需求、提问和汇报。对外消息默认由对接人确认后发送。</p>`);}
PAGES['portal']=()=>{const narrow=window.matchMedia('(max-width: 900px)').matches;return egFrame('portal',`<div class="row wrap" style="margin-bottom:16px"><span class="small">状态预览</span>${['正常','异常','空'].map(s=>`<button class="chip ${egState.preview===s?'on':''}" onclick="egSet('preview','${s}')">${s}</button>`).join('')}<label class="row small"><input type="checkbox" ${egState.aiVisible?'checked':''} onchange="egSet('aiVisible',this.checked)">门户展示 AI 助手</label></div>${egState.preview==='异常'?'<div class="note danger" role="alert">连接异常。已显示的会话仍可查看，暂不能发送或签认。</div>':''}${narrow?`<div class="row wrap" style="margin-bottom:12px">${[['list','话题'],['chat','会话'],['detail','详情']].map(([k,t])=>egBtn(t,`egSet('level','${k}')`,egState.level===k?'primary':'')).join('')}</div><div class="stack">${egState.level==='list'?egThreadList():egState.level==='chat'?egConversation():egDetails()}</div>`:`<div class="grid g12"><div class="c3 stack" style="min-width:0">${egThreadList()}</div><div class="c6 stack" style="min-width:0">${egConversation()}</div><div class="c3 stack" style="min-width:0">${egDetails()}</div></div>`}`);};
function egQuestion(i){if(!egWritable())return;egState.thread='T1';egState.level='chat';egState.input='关于 BL-7 v1「'+egItems[i].title+'」，我的疑问是：';go('portal');}
function egSign(){if(!egWritable()||!egState.read||egState.signed)return;egState.signed=true;egConversion.requirement='R-21';egConversion.version=1;egState.messages.T1=(egState.messages.T1||[]).concat([{author:egState.contact,text:'已签认 BL-7 v1。'},{author:'Morgan',text:'此版本已成为基线；之后的改动走变更。已关联账单中心项目。'}]);route();toast('已签认 BL-7 v1');}
PAGES['portal-baseline']=(id)=>{if(id!=='BL-7')return egFrame('portal-baseline/BL-7',card('需求确认单','<div class="empty">未找到此需求确认单。</div>'+egBtn('返回会话',"go('portal')")));return egFrame('portal-baseline/BL-7',`<div class="stack">${card('BL-7 v1 · 账单中心二期',`<dl class="kv"><dt>账户 / 联系人</dt><dd>Contoso · Lee（可签认）· Zhao（只读）</dd><dt>状态</dt><dd><span class="badge ${egState.signed?'b-ok':'b-warn'}">${egState.signed?'已签认':'待甲方签认'}</span></dd><dt>来源</dt><dd>《账单中心二期需求说明书.docx》 · T1</dd><dt>摘要</dt><dd>3 个阶段 · 5 个里程碑 · 14 条需求项 · 21 条验收标准 · 2 条范围外</dd></dl>${egBtn('返回会话',"egSelect('T1')",'ghost')}`)}${['需求与口径','导出与权限','交付与说明'].map((phase,p)=>card('阶段 '+(p+1)+' · '+phase,`<div class="stack">${egItems.map((item,i)=>item.phase!==p?'':`<div><div class="row wrap"><b class="grow">${item.id} · ${item.title}</b><span class="badge b-info">优先级：${item.priority}</span>${egBtn('有疑问',`egQuestion(${i})`,'sm',!egWritable())}</div><details style="margin-top:8px"><summary style="cursor:pointer">验收标准 · ${item.criteria.length} 条</summary><div class="stack small" style="padding:12px">${item.criteria.map((c,n)=>`<div>标准 ${i+1}.${n+1}：${c}</div>`).join('')}</div></details></div>`).join('<div class="sep"></div>')}</div>`)).join('')}${card('里程碑与日期',`<div class="table-wrap"><table><thead><tr><th>里程碑</th><th>阶段</th><th>日期</th></tr></thead><tbody>${egMilestones.map(m=>`<tr><td>${m.id} · ${m.title}</td><td>${m.phase+1}</td><td class="mono">${m.date}</td></tr>`).join('')}</tbody></table></div>`)}${card('范围外','<p>1. 自动报价与合同生成。</p><p>2. 跨账户结算与币种兑换。</p>')}${card('版本历史',`<dl class="kv"><dt>版本</dt><dd>v1 · 2026-10-12</dd><dt>整理 / 确认</dt><dd>对接组整理 · Morgan 确认</dd><dt>签认记录</dt><dd>${egState.signed?'Lee · 已签认 BL-7 v1':'尚未签认'}</dd></dl>`)}${card('签认此版本',`<p class="note info">签认后成为基线；之后的改动走变更。瀑布与清单需求须签认后再开始。</p><label class="row"><input type="checkbox" ${egState.read?'checked':''} ${!egWritable()||egState.signed?'disabled':''} onchange="egSet('read',this.checked)">我已阅读</label><div class="row wrap" style="margin-top:12px">${egBtn('签认此版本','egSign()','primary',!egWritable()||!egState.read||egState.signed)}${egBtn('返回会话',"egSelect('T1')",'ghost')}</div><p class="muted small">${egState.signed?'此版本已签认，不能重复签认。':egReason()||(!egState.read?'请先勾选「我已阅读」。':'你将以 Lee 身份签认 BL-7 v1。')}</p>`)}</div>`);};
PAGES['portal-progress']=()=>egFrame('portal-progress',`<div class="stack">${card('里程碑总览','<dl class="kv"><dt>账户</dt><dd>Contoso</dd><dt>项目</dt><dd>账单中心</dd><dt>进度</dt><dd>M2 导出能力：4 / 6 项完成，预计 10-27</dd><dt>更新时间</dt><dd>2026-10-12 · Morgan 发布</dd></dl>')}${card('T1 · 账单中心二期 SOW',`<div class="stack">${egMilestones.map(m=>`<div class="row wrap"><b class="grow">${m.id} · ${m.title}</b><span class="mono">${m.date}</span><span class="badge ${m.id==='M1'&&egState.signed?'b-ok':'b-info'}">${m.id==='M1'&&egState.signed?'已签认':m.status}</span></div>`).join('<div class="sep"></div>')}</div><p class="note info">二期范围须签认后开始。导出能力进度与 BIL#3 为已有交付进度。</p>`)}${card('T2 / T3 · 线程进展','<dl class="kv"><dt>十月优化清单</dt><dd>已确认 3 · 澄清中 2 · 已纳入需求 2 · 不做 1；尚无已承诺的里程碑日期</dd><dt>导出权限问题</dt><dd>容差内快速通道变更，已通知你；尚无独立里程碑日期</dd></dl>')}${card('最近的进度卡',`<div class="stack"><div><b>M2 导出能力：4 / 6 项完成，预计 10-27</b><p class="muted small">T1 · 账单中心 · 2026-10-12 · Morgan 发布</p></div><div class="sep"></div><div><b>BIL#3 · 待验收</b><p class="muted small">账单中心 · CSV 导出、字段排序、失败重试提示</p>${egBtn('去验收',"go('portal-accept')",'primary')}</div></div>`)}</div>`);
PAGES['portal-submit']=()=>{setTimeout(()=>go('portal'),0);return '';};
PAGES['portal-clarify']=()=>{setTimeout(()=>go('portal'),0);return '';};
Object.assign(TITLES,{'portal':'对接会话','portal-baseline':'需求确认单','portal-progress':'进度','portal-submit':'对接会话','portal-clarify':'对接会话'});
Object.assign(NAVPARENT,{'portal':'portal','portal-baseline':'portal','portal-progress':'portal','portal-submit':'portal','portal-clarify':'portal'});
const egMedia=window.matchMedia('(max-width: 900px)');
egMedia.addEventListener('change',()=>{if(location.hash.split('/')[1]==='portal')route();});
